     3	/// A Show Me in flight: its entries, where it is, and what it has answered.
     4	struct TutorialShowMeRun {
     5	    let entries: [TutorialShowMe]
     6	    let step: Int
     7	    let generation: Int
     8	    var results: [String] = []
     9	    var paths: [String] = []
    10	}
    11	
    12	/// Show Me (spec §11 TU-3, TU-9): the step done the way the app already does
    13	/// it, its entries in order, never blocking main.
    14	///
    15	/// **The tool form** resolves TU-2 (9)'s variables, then goes through
    16	/// `AgentLane.shared.submit` pinned to the runner's document — the
    17	/// assistant's path: the argument gate, the lane's lock, ordinary undo — with
    18	/// ask-first answered yes, since the press is the ask. An `export` call's
    19	/// `path` is made free first (`RecordingFiles.uniqueURL`, the Finder's
    20	/// `<stem> (2).<ext>` rule), so a Show Me never overwrites a file, and the
    21	/// outcome names the file. Its completion hops back to main — a documented
    22	/// `DispatchQueue.main.async` seam — and is dropped when the runner has been
    23	/// replaced or exited. **The menu form** looks the path up in the built menu
    24	/// bar for the editor's window (`UIMenu.lookup`, compiled in every build) and
    25	/// runs the item through `UIMenu.perform`, refused when absent, when nothing
    26	/// answers it or its validator greys it, and when nothing handled it.
    27	///
    28	/// An entry that errors stops the list with its own text; the step stays,
    29	/// and the earlier entries' edits stay. Evaluations are held while it runs
    30	/// (`TutorialRunner.trigger`) and one runs after the last entry.
    31	extension TutorialRunner {
    32	    func showMe() throws {
    33	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
    34	        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
    35	        let entries = currentStep.showMe
    36	        guard !entries.isEmpty else { throw TutorialRefusal(sentence: "This step has no Show Me.") }
    37	        guard document != nil else { throw TutorialRefusal(sentence: "This window has no project.") }
    38	        showMeGeneration += 1
    39	        showMeRunning = true
    40	        showMeRun = TutorialShowMeRun(entries: entries, step: index + 1, generation: showMeGeneration)
    41	        runShowMeEntry(0)
    42	    }
    43	
    44	    private func runShowMeEntry(_ at: Int) {
    45	        guard let run = showMeRun else { return }
    46	        guard at < run.entries.count else {
    47	            finishShowMe(error: nil)
    48	            return
    49	        }
    50	        guard let document else {
    51	            finishShowMe(error: "The tutorial's project is no longer open.")
    52	            return
    53	        }
    54	        let before = Set(document.editedProject.snapshot.clips.map(\.id))
    55	        switch run.entries[at] {
    56	        case .menu(let path):
    57	            if let refusal = performMenu(path) {
    58	                finishShowMe(error: refusal)
    59	                return
    60	            }
    61	            showMeRun?.results.append(path.joined(separator: " ▸ "))
    62	            noteCreated(since: before)
    63	            runShowMeEntry(at + 1)
    64	        case .tool(let name, let args):
    65	            let json: String
    66	            do {
    67	                var resolved = try TutorialVariables.resolve(
    68	                    args, selection: selectionAtStart, created: created, snapshot: document.editedProject.snapshot,
    69	                    playhead: document.playhead) as? [String: Any] ?? [:]
    70	                if name == "export", let path = resolved["path"] as? String {
    71	                    let free = Self.freeURL(for: path).path
    72	                    resolved["path"] = free
    73	                    showMeRun?.paths.append(free)
    74	                }
    75	                let data = try JSONSerialization.data(withJSONObject: resolved)
    76	                json = String(decoding: data, as: UTF8.self)
    77	            } catch let refusal as TutorialRefusal {
    78	                finishShowMe(error: refusal.sentence)
    79	                return
    80	            } catch {
    81	                finishShowMe(error: error.localizedDescription)
    82	                return
    83	            }
    84	            let generation = run.generation
    85	            AgentLane.shared.submit(
    86	                tool: name, argumentsJSON: json, document: document,
    87	                askFirst: { _, answer in answer(true) },
    88	                completion: { result in
    89	                    DispatchQueue.main.async { [weak self] in
    90	                        guard let self, self.showMeGeneration == generation,
    91	                              self.editor?.tutorialRunner === self
    92	                        else { return }
    93	                        self.toolAnswered(result, entry: at, before: before)
    94	                    }
    95	                })
    96	        }
    97	    }
    98	
    99	    private func toolAnswered(_ result: String, entry: Int, before: Set<UInt32>) {
   100	        let reply = (try? JSONSerialization.jsonObject(with: Data(result.utf8))) as? [String: Any]
   101	        let content = reply?["content"] as? [[String: Any]] ?? []
   102	        let text = content.compactMap { $0["text"] as? String }.joined(separator: "\n")
   103	        showMeRun?.results.append(text)
   104	        if (reply?["isError"] as? Bool) ?? true {
   105	            finishShowMe(error: text.isEmpty ? "The call failed." : text)
   106	            return
   107	        }
   108	        if let document { noteCreated(since: before, in: document) }
   109	        runShowMeEntry(entry + 1)
   110	    }
   111	
   112	    /// `$created` becomes what this call added, when it added any.
   113	    private func noteCreated(since before: Set<UInt32>, in document: ProjectDocument) {
   114	        let snapshot = document.editedProject.snapshot
   115	        let added = snapshot.clips.map(\.id).filter { !before.contains($0) }
   116	        if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
   117	    }
   118	
   119	    private func noteCreated(since before: Set<UInt32>) {
   120	        if let document { noteCreated(since: before, in: document) }
   121	    }
   122	
   123	    private func finishShowMe(error: String?) {
   124	        guard let run = showMeRun else { return }
   125	        lastShowMe = TutorialShowMeOutcome(
   126	            step: run.step, ok: error == nil, error: error, results: run.results, paths: run.paths)
   127	        showMeRun = nil
   128	        showMeRunning = false
   129	        heldEvaluation = false
   130	        trigger()
   131	    }
   132	
   133	    /// The menu form: nil once the item ran, else why not.
   134	    private func performMenu(_ path: [String]) -> String? {
   135	        let shown = path.joined(separator: " ▸ ")
   136	        let window = editor?.view.window
   137	        guard case .item(let item) = UIMenu.lookup(path, window: window) else {
   138	            return "The menu bar has no \(shown)."
   139	        }
   140	        guard let target = UIMenu.target(for: item, window: window),
   141	              UIMenu.isEnabled(item, target: target)
   142	        else { return "\(shown) is not available now." }
   143	        guard UIMenu.perform(item, target: target, window: window) else {
   144	            return "\(shown) was not handled."
   145	        }
   146	        return nil
   147	    }
   148	
   149	    /// An `export` path, tilde-expanded, made free by the Finder's rule.
   150	    static func freeURL(for path: String) -> URL {
   151	        let url = URL(fileURLWithPath: (path as NSString).expandingTildeInPath)
   152	        return RecordingFiles.uniqueURL(
   153	            in: url.deletingLastPathComponent(), stem: url.deletingPathExtension().lastPathComponent,
   154	            ext: url.pathExtension)
   155	    }
   156	}
