    /// The project's `clips`, as the core writes them, by id. Main only.
    static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
        if let parsed, parsed.handle === project { return parsed.clips }
        var clips: [UInt32: [String: Any]] = [:]
        if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
            as? [String: Any], let list = top["clips"] as? [[String: Any]]
        {
