    /// The last handle read and its clips by id: `changed` reads one handle
    /// many times between edits.
    private static var parsed: (handle: ReelProject, clips: [UInt32: [String: Any]])?

    /// The project's `clips`, as the core writes them, by id. Main only.
    static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
        if let parsed, parsed.handle === project { return parsed.clips }
        var clips: [UInt32: [String: Any]] = [:]
        if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
            as? [String: Any], let list = top["clips"] as? [[String: Any]]
        {
            for clip in list {
                if let id = (clip["id"] as? NSNumber)?.uint32Value { clips[id] = clip }
            }
        }
        parsed = (project, clips)
        return clips
    }

    /// Lets go of the cached handle, so a closed document's project is not
    /// kept alive; a runner calls it as it goes. Main only.
    static func forgetClipJSON() {
        parsed = nil
    }

